import{_ as a,o as t,c as n,a0 as o}from"./chunks/framework.veCcaNqE.js";const m=JSON.parse('{"title":"Framework Example 4: Flight Recovery Branch-and-Price — Overview","description":"","frontmatter":{},"headers":[],"relativePath":"examples/framework-example4.md","filePath":"examples/framework-example4.md"}'),r={name:"examples/framework-example4.md"};function s(i,e,c,l,d,h){return t(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="framework-example-4-flight-recovery-branch-and-price-—-overview" tabindex="-1">Framework Example 4: Flight Recovery Branch-and-Price — Overview <a class="header-anchor" href="#framework-example-4-flight-recovery-branch-and-price-—-overview" aria-label="Permalink to &quot;Framework Example 4: Flight Recovery Branch-and-Price — Overview&quot;">​</a></h1><p><a href="/ospf/zh-cn/examples/framework-example4.html">中文</a></p><h2 id="_1-overview" tabindex="-1">1. Overview <a class="header-anchor" href="#_1-overview" aria-label="Permalink to &quot;1. Overview&quot;">​</a></h2><p>Demo4 is an architecture sample. <code>Application</code> is empty, while the generic quantity sample is executable; context pages describe implemented contracts without claiming that one production model is assembled.</p><h2 id="_2-contexts-and-dependencies" tabindex="-1">2. Contexts and Dependencies <a class="header-anchor" href="#_2-contexts-and-dependencies" aria-label="Permalink to &quot;2. Contexts and Dependencies&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Context</th><th>Responsibility</th><th>Dependency</th></tr></thead><tbody><tr><td>Task and rule</td><td>Tasks, connections, and business rules</td><td>Input configuration</td></tr><tr><td>Crew, cargo, passenger</td><td>Resources and transport demand</td><td>Tasks and corresponding resource data</td></tr><tr><td>Bunch generation</td><td>Searches policy-compatible flight bunches</td><td>Task, rule, and resource contexts</td></tr><tr><td>Bunch compilation</td><td>Compiles columns into coverage, capacity, and objective expressions</td><td>Generated bunches and business pipelines</td></tr><tr><td>Bunch selection</td><td>Coordinates column selection and branch-and-price policy</td><td>Generation and compilation contracts</td></tr></tbody></table><h2 id="_3-concepts-sets-and-predicates" tabindex="-1">3. Concepts, Sets, and Predicates <a class="header-anchor" href="#_3-concepts-sets-and-predicates" aria-label="Permalink to &quot;3. Concepts, Sets, and Predicates&quot;">​</a></h2><p>The vocabulary includes flight tasks, connections, crews, cargo, passengers, and flight bunches. Predicates express feasible transitions, resource compatibility, and column acceptance. Each context defines its own sets rather than merging all resources into an unowned global set.</p><h2 id="_4-variables-and-intermediate-values" tabindex="-1">4. Variables and Intermediate Values <a class="header-anchor" href="#_4-variables-and-intermediate-values" aria-label="Permalink to &quot;4. Variables and Intermediate Values&quot;">​</a></h2><p>Bunch compilation owns column usage and derives task-, aircraft-, and connection-related expressions from column coefficients. Generation and selection describe service and callback contracts without duplicating master variables. The context pages define precise notation and domains.</p><h2 id="_5-assertions-constraints-and-objectives" tabindex="-1">5. Assertions, Constraints, and Objectives <a class="header-anchor" href="#_5-assertions-constraints-and-objectives" aria-label="Permalink to &quot;5. Assertions, Constraints, and Objectives&quot;">​</a></h2><p>Compilation provides task, connection, aircraft, and related resource contracts. Passenger and other business pipelines add their rows and objectives when enabled. An empty top-level <code>Application</code> defines no complete global objective; these contracts must not be presented as an assembled end-to-end model.</p><h2 id="_6-algorithms-and-lifecycle" tabindex="-1">6. Algorithms and Lifecycle <a class="header-anchor" href="#_6-algorithms-and-lifecycle" aria-label="Permalink to &quot;6. Algorithms and Lifecycle&quot;">​</a></h2><p>The architectural sequence is to build business policies, initialize dual information, generate bunches, compile the master, and continue according to reduced costs and branch policies. The generic-quantity example separately demonstrates quantity types and linear-symbol APIs.</p><h2 id="_7-register-→-construct-→-solve-→-analyze" tabindex="-1">7. Register → Construct → Solve → Analyze <a class="header-anchor" href="#_7-register-→-construct-→-solve-→-analyze" aria-label="Permalink to &quot;7. Register → Construct → Solve → Analyze&quot;">​</a></h2><p>Each child page explains its registrable symbols, pipelines, and callbacks. Kotlin&#39;s top-level <code>Application</code> is a placeholder, so this page describes context composition rather than an unavailable end-to-end solver call chain.</p><h2 id="_8-source-entry-points" tabindex="-1">8. Source Entry Points <a class="header-anchor" href="#_8-source-entry-points" aria-label="Permalink to &quot;8. Source Entry Points&quot;">​</a></h2><ul><li><a href="https://github.com/fuookami/ospf-kotlin/tree/main/ospf-kotlin-example/src/main/fuookami/ospf/kotlin/example/framework_demo/demo4" target="_blank" rel="noreferrer">Kotlin Demo4 source</a></li><li><a href="https://github.com/fuookami/ospf-rust/tree/main/ospf-rust-example/src/framework/demo4" target="_blank" rel="noreferrer">Rust Demo4 source</a></li></ul><h2 id="_9-kotlin-rust-comparison-and-design-decisions" tabindex="-1">9. Kotlin/Rust Comparison and Design Decisions <a class="header-anchor" href="#_9-kotlin-rust-comparison-and-design-decisions" aria-label="Permalink to &quot;9. Kotlin/Rust Comparison and Design Decisions&quot;">​</a></h2><p>Both languages have framework-example directories, but matching names do not establish equal top-level completeness. The pages use Kotlin context contracts as the reference and distinguish architectural composition from an executed global model.</p><h2 id="_10-context-model-pages" tabindex="-1">10. Context Model Pages <a class="header-anchor" href="#_10-context-model-pages" aria-label="Permalink to &quot;10. Context Model Pages&quot;">​</a></h2><p><a href="./framework-example4/domain-models.html">Open the context index</a> for task, rule, crew, cargo, passenger, bunch generation, bunch compilation, and bunch selection.</p><h2 id="_11-change-log" tabindex="-1">11. Change Log <a class="header-anchor" href="#_11-change-log" aria-label="Permalink to &quot;11. Change Log&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Version</th><th>Change</th><th>Reason</th></tr></thead><tbody><tr><td>1.1</td><td>Aligned bilingual overviews, notation, and source entry points</td><td>Keep the overview consistent with its context models</td></tr></tbody></table>',24)])])}const u=a(r,[["render",s]]);export{m as __pageData,u as default};
